import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './HomePage.css';

function HomePage({ user }) {
  const [userEmail, setUserEmail] = useState('');
  const [availableSlots, setAvailableSlots] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [selectedSlot, setSelectedSlot] = useState(null);
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [totalCost, setTotalCost] = useState(0);
  const [message, setMessage] = useState('');

  const navigate = useNavigate();

  useEffect(() => {
    const storedEmail = localStorage.getItem('userEmail');
    if (user?.email) {
      setUserEmail(user.email);
    } else if (storedEmail) {
      setUserEmail(storedEmail);
    } else {
      navigate('/');
    }
  }, [user, navigate]);

  const fetchSlots = () => {
    fetch('http://localhost:8081/api/slots/available')
      .then(res => res.json())
      .then(data => setAvailableSlots(data))
      .catch(err => console.error('Error fetching slots:', err));
  };

  const fetchBookings = () => {
    fetch(`http://localhost:8081/api/bookings/user/1`) // replace with logged-in user's ID
      .then(res => res.json())
      .then(data => setBookings(data))
      .catch(err => console.error('Error fetching bookings:', err));
  };

  useEffect(() => {
    fetchSlots();
    fetchBookings();
  }, []);

  const openBookingModal = (slot) => {
    setSelectedSlot(slot);
    setVehicleNumber('');
    setStartTime('');
    setEndTime('');
    setTotalCost(0);
    setShowModal(true);
  };

  const calculateCost = (start, end, rate) => {
    const startDate = new Date(start);
    const endDate = new Date(end);
    const diffHours = Math.abs(endDate - startDate) / 36e5;
    return (diffHours * rate).toFixed(2);
  };

  const handleBooking = () => {
    if (!vehicleNumber || !startTime || !endTime) {
      setMessage('Please fill all booking details.');
      return;
    }

    const bookingData = {
      userId: 1,
      parkingSlotId: selectedSlot.id,
      vehicleNumber,
      startTime,
      endTime
    };

    fetch('http://localhost:8081/api/bookings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(bookingData)
    })
      .then(async (res) => {
        if (res.ok) {
          await res.json();
          setMessage('Booking Confirmed!');
          setShowModal(false);
          fetchSlots();
          fetchBookings();
        } else {
          const errorText = await res.text();
          setMessage(`Error: ${errorText}`);
        }
      })
      .catch(err => {
        console.error('Error creating booking:', err);
        setMessage('Error occurred while booking.');
      });
  };

  const handleLogout = () => {
    localStorage.removeItem('userEmail');
    navigate('/');
  };

  return (
    <div className="dashboard-container">
      {/* Navbar */}
      <header className="navbar">
        <div className="logo">🚗 ParkingPro</div>
        <div className="user-info">
          {userEmail && <span>{userEmail}</span>}
          <button className="logout-btn" onClick={handleLogout}>Logout</button>
        </div>
      </header>

      {/* Slots Section */}
      <section className="slots-section">
        <h2>Available Slots</h2>
        <div className="slots-grid">
          {availableSlots.map(slot => (
            <div className="slot-card" key={slot.id}>
              <h3>{slot.slotNumber}</h3>
              <p>Type: {slot.slotType}</p>
              <p>Rate: ${slot.hourlyRate}/hr</p>
              <button onClick={() => openBookingModal(slot)}>Book Now</button>
            </div>
          ))}
        </div>
      </section>

      {/* Booking History */}
      <section className="bookings-section">
        <h2>My Bookings</h2>
        <table>
          <thead>
            <tr>
              <th>Slot</th>
              <th>Vehicle</th>
              <th>Start</th>
              <th>End</th>
              <th>Status</th>
              <th>Total Cost</th>
            </tr>
          </thead>
          <tbody>
            {bookings.map(b => (
              <tr key={b.id}>
                <td>{b.parkingSlot?.slotNumber}</td>
                <td>{b.vehicleNumber}</td>
                <td>{b.startTime}</td>
                <td>{b.endTime}</td>
                <td>{b.status}</td>
                <td>${b.totalCost}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      {/* Booking Modal */}
      {showModal && (
        <div className="modal-overlay">
          <div className="modal">
            <h2>Book Slot {selectedSlot.slotNumber}</h2>
            <input
              type="text"
              placeholder="Vehicle Number"
              value={vehicleNumber}
              onChange={(e) => setVehicleNumber(e.target.value)}
            />
            <label>Start Time</label>
            <input
              type="datetime-local"
              value={startTime}
              onChange={(e) => {
                setStartTime(e.target.value);
                if (endTime) {
                  setTotalCost(calculateCost(e.target.value, endTime, selectedSlot.hourlyRate));
                }
              }}
            />
            <label>End Time</label>
            <input
              type="datetime-local"
              value={endTime}
              onChange={(e) => {
                setEndTime(e.target.value);
                if (startTime) {
                  setTotalCost(calculateCost(startTime, e.target.value, selectedSlot.hourlyRate));
                }
              }}
            />
            <p>Total Cost: ${totalCost}</p>
            <div className="modal-actions">
              <button onClick={handleBooking}>Confirm Booking</button>
              <button className="cancel-btn" onClick={() => setShowModal(false)}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {message && <div className="toast">{message}</div>}
    </div>
  );
}

export default HomePage;
